//! Writers for the maps the build script cannot compute itself.
//!
//! `build.rs` may not link the engine it is building, so the tables that come
//! out of the engine (`derived_by_form`, `derived_nominal`,
//! `derived_modifiers`, `pronoun_forms`) are generated by
//! `tools/src/bin/gen_derived.rs` after a `RULES`/sanalista change and
//! committed like every other blob. The writer here is shared with that tool;
//! the reader is `src/expand/derived.rs`.
//!
//! Keep this tree free of engine dependencies for the same reason as the
//! build-script writers: the tool supplies the computed rows.

pub mod table;
